    "support.eyebrow": "Support",
    "support.title": "Here for you <em>at life's turning points</em>.",
    "support.lead": "We support members from an annual budget approved by the Union Committee. You can apply once you've been a member for at least 3 months and pay your dues regularly. There's no waiting period for funeral support.",
    "support.group.social": "Family and life events",
    "support.group.rest": "Rest and recreation",
    "support.s1.v": "HUF 25,000",
    "support.s1.t": "Birth of a child",
    "support.s1.d": "Per child. Please attach the birth certificate.",
    "support.s2.v": "HUF 15,000",
    "support.s2.t": "Back to school",
    "support.s2.d": "Per child in public education. If both parents are members, only one of them can claim it.",
    "support.s3.v": "HUF 20,000",
    "support.s3.t": "Summer camp",
    "support.s3.d": "Per child, for any summer camp, with the invoice for the fee. You can choose either the back-to-school or the camp support.",
    "support.s4.v": "HUF 50,000 / 20,000",
    "support.s4.t": "Funeral support",
    "support.s4.d": "On the death of a direct or collateral relative, within 6 months of the funeral. Retired members are also eligible.",
    "support.s5.v": "from HUF 15,000",
    "support.s5.t": "Sickness support",
    "support.s5.d": "After at least 4 weeks of continuous sick leave. From the second month it rises by HUF 5,000 per month.",
    "support.s6.v": "up to HUF 50,000",
    "support.s6.t": "Emergency support",
    "support.s6.d": "For natural disasters, theft, burglary, accidents, or a spouse's long-term illness or unemployment, with an invoice or certificate.",
    "support.s7.v": "once a year",
    "support.s7.t": "Travel for treatment",
    "support.s7.d": "If your health requires treatment far from home: the return travel cost, with a VAT invoice made out to Chinoin VDSZ.",
    "support.s8.v": "HUF 60,000",
    "support.s8.t": "Interest-free loan",
    "support.s8.d": "Once a year, repaid in 6 monthly instalments of HUF 10,000 deducted from your pay.",
    "support.r1.v": "HUF 15,000",
    "support.r1.t": "Balatonszemes holiday home",
    "support.r1.d": "Per member, for a holiday at the union's Balatonszemes holiday home, on top of the discounted price.",
    "support.r2.v": "HUF 5,000 / night",
    "support.r2.t": "Balatonlelle holiday home",
    "support.r2.d": "Per night, for a holiday at the union's Balatonlelle holiday home.",
    "support.r3.v": "HUF 20,000",
    "support.r3.t": "Multi-day trip",
    "support.r3.d": "Per member, for a multi-day trip organised by the union.",
    "support.r4.v": "2 people",
    "support.r4.t": "Wellness voucher",
    "support.r4.d": "One voucher admits two people at 26 spas nationwide. Ask your chief shop steward.",
    "support.note": "Social support is available to active members in employment, up to HUF 50,000 in well-justified cases; larger amounts are decided by the Stewards' Council. If the monthly budget runs out, approved support is paid the following month.",
    "support.note2": "You can use one holiday support per year. Holiday and wellness support are available to active employees of the Sanofi group in Hungary and of Euroapi Hungary Kft. The exact conditions are in the rules available in the member area.",
    "claim.eyebrow": "How to apply",
